    const std::uint8_t *const aSourceLanes[4] = {
        Soccer2::mShrinkLaneA,
        Soccer2::mShrinkLaneB,
        Soccer2::mShrinkLaneC,
        Soccer2::mShrinkLaneD
    };

    std::uint8_t *const aDestinationLanes[4] = {
        Soccer2::mCrushA,
        Soccer2::mCrushB,
        Soccer2::mCrushC,
        Soccer2::mCrushD
    };

    for (std::size_t aRollIndex=0U; aRollIndex<256U; aRollIndex++) {
        const FoldingRoll &aRoll = aRolls[aRollIndex];
        const std::size_t aDestinationLaneIndex = aRollIndex % aDestinationLaneCount;
        const std::size_t aDestinationBlockIndex = aRollIndex / aDestinationLaneCount;
        std::uint8_t *const aDestination = &aDestinationLanes[aDestinationLaneIndex][aDestinationBlockIndex * aBlockByteCount];

        const std::uint8_t *const aSourceA = &aSourceLanes[aRoll.mSourceLanes[0U]][aRoll.mSourceBlocks[0U] * aBlockByteCount];
        const std::uint8_t *const aSourceB = &aSourceLanes[aRoll.mSourceLanes[1U]][aRoll.mSourceBlocks[1U] * aBlockByteCount];
        const std::uint8_t *const aSourceC = &aSourceLanes[aRoll.mSourceLanes[2U]][aRoll.mSourceBlocks[2U] * aBlockByteCount];
        const std::uint8_t *const aSourceD = &aSourceLanes[aRoll.mSourceLanes[3U]][aRoll.mSourceBlocks[3U] * aBlockByteCount];
        const std::uint8_t *const aSourceE = &aSourceLanes[aRoll.mSourceLanes[4U]][aRoll.mSourceBlocks[4U] * aBlockByteCount];
        const std::uint8_t *const aSourceF = &aSourceLanes[aRoll.mSourceLanes[5U]][aRoll.mSourceBlocks[5U] * aBlockByteCount];
        const std::uint8_t *const aSourceG = &aSourceLanes[aRoll.mSourceLanes[6U]][aRoll.mSourceBlocks[6U] * aBlockByteCount];
        const std::uint8_t *const aSourceH = &aSourceLanes[aRoll.mSourceLanes[7U]][aRoll.mSourceBlocks[7U] * aBlockByteCount];

        for (std::size_t aIndex=0U; aIndex<aBlockByteCount; aIndex++) {
            const std::size_t aIndexForward = aIndex;
            const std::size_t aIndexBackward = aBlockByteCount - 1U - aIndex;

            std::uint32_t aFoldValueA = 0U;
            aFoldValueA |= static_cast<std::uint32_t>(aSourceA[aIndexForward]) <<  0U;
            aFoldValueA |= static_cast<std::uint32_t>(aSourceB[aIndexBackward]) <<  8U;
            aFoldValueA |= static_cast<std::uint32_t>(aSourceC[aIndexForward]) << 16U;
            aFoldValueA |= static_cast<std::uint32_t>(aSourceD[aIndexBackward]) << 24U;
            aFoldValueA = TwistMix32::DiffuseA(aFoldValueA);

            std::uint32_t aFoldValueB = 0U;
            aFoldValueB |= static_cast<std::uint32_t>(aSourceE[aIndexForward]) <<  0U;
            aFoldValueB |= static_cast<std::uint32_t>(aSourceF[aIndexBackward]) <<  8U;
            aFoldValueB |= static_cast<std::uint32_t>(aSourceG[aIndexForward]) << 16U;
            aFoldValueB |= static_cast<std::uint32_t>(aSourceH[aIndexBackward]) << 24U;
            aFoldValueB = TwistMix32::DiffuseA(aFoldValueB);

            std::uint16_t aFoldValue = 0U;
            aFoldValue |= static_cast<std::uint16_t>(static_cast<std::uint8_t>(aFoldValueA)) << 0U;
            aFoldValue |= static_cast<std::uint16_t>(static_cast<std::uint8_t>(aFoldValueB)) << 8U;
            aFoldValue = TwistMix16::DiffuseA(aFoldValue);
            aDestination[aIndex] = static_cast<std::uint8_t>(aFoldValue);
        }
    }
